const INITIAL_CONFIG = {"siteName":"ColoringTool","domain":"coloringtool.com","logo":{"imageSrc":"","icon":"🎨","mode":"icon_text","text":"ColoringTool"},"siteTitle":"ColoringTool.com — Free Online Coloring Pages for Kids & Painting Games","tagline":"Enjoy free drawings to paint and color online — fun coloring games for kids ages 3 to 10. Animals, unicorns, Christmas and more. No download, no signup!","theme":{"primary":"#6366F1","primaryDark":"#4F46E5","primaryHover":"#4338CA","secondary":"#EC4899","accentGold":"#F59E0B","accentCyan":"#06B6D4","accentEmerald":"#10B981","bgCanvas":"#F8FAFC","cardBg":"#FFFFFF","textMain":"#1E293B","textMuted":"#64748B"},"admin":{"username":"admin","password":"admin123"},"analytics":{"enabled":true,"measurementId":"G-COLORINGTOOL","sendPageView":true,"trackDrawingClicks":true,"trackArtworkSaves":true,"trackPrints":true},"seo":{"defaultTitle":"ColoringTool.com — Free Online Coloring Pages for Kids & Painting Games","defaultDescription":"Enjoy 100+ free online coloring pages to paint and color online. Fun interactive coloring games for kids with animals, unicorns, princesses, Christmas and more.","keywords":"coloring pages, free coloring pages, online coloring for kids, coloring games, printable coloring sheets, kids painting online","canonicalBase":"https://coloringtool.com","ogImage":"/my-favicon/favicon-96x96.png","googleVerification":"","bingVerification":"","robotsDirectives":"index, follow, max-image-preview:large","robotsTxt":"User-agent: *\nAllow: /\nDisallow: /admin/\nDisallow: /api/admin/\n\nSitemap: https://coloringtool.com/sitemap.xml","ratingValue":"4.9","ratingCount":"1280"},"adsense":{"enabled":false,"publisherId":"ca-pub-1234567890123456","autoAds":false,"headerSlot":"1234567890","sidebarSlot":"2345678901","belowGameSlot":"3456789012","adsTxtContent":"google.com, pub-1234567890123456, DIRECT, f08c47fec0942fa0"},"aboutUsHtml":"\n    <h2>About ColoringTool.com</h2>\n    <p>Welcome to <strong>ColoringTool.com</strong>, the premier online destination for free, safe, and engaging digital coloring activities for young children ages 3 to 10. Our mission is to empower children to unleash their imagination, discover colors, and build fine motor skills through playful, accessible creative tools directly in their web browser.</p>\n    \n    <h2>Our Creative Philosophy</h2>\n    <p>Drawing and painting are essential to early childhood cognitive development. At ColoringTool.com, we design every illustration with bold contours and engaging themes so children can feel immediate pride and joy in their artwork. Whether filling regions with tap-to-fill or experimenting with digital brushes, children can express their unique visual voice without mess or complexity.</p>\n\n    <h2>Safe, Screen-Positive Experience</h2>\n    <p>We strictly follow child-safe design standards. There are no mandatory logins, no account creations, and no downloads required. All drawing activities are completely anonymous, instant, and privacy-first.</p>\n\n    <h2>Co-Viewing & Shared Connection</h2>\n    <p>Our activities are crafted for children and parents, teachers, and caregivers to explore together. Talking about colors, naming animals, and sharing storytelling around each drawing transforms digital time into meaningful connection and learning.</p>\n  ","privacyPolicyHtml":"\n    <h2>Privacy Policy — ColoringTool.com</h2>\n    <p><strong>Effective Date:</strong> November 15, 2026</p>\n    <p>Welcome to <strong>ColoringTool.com</strong> (\"we\", \"us\", or \"our\"). We are committed to providing a safe, joyful, educational, and family-friendly environment for children, parents, teachers, and guardians worldwide. This Privacy Policy outlines our transparent data practices, child-first privacy principles, and full compliance with the <strong>Children's Online Privacy Protection Act (COPPA)</strong>, <strong>Google AdSense Publisher Policies</strong>, <strong>General Data Protection Regulation (GDPR)</strong>, and <strong>California Consumer Privacy Act (CCPA/CPRA)</strong>.</p>\n\n    <h2>1. Children’s Privacy (Strict COPPA Compliance)</h2>\n    <p>ColoringTool.com is designed for all ages, with special care for children under the age of 13. Protecting children’s privacy online is our highest priority.</p>\n    <ul>\n      <li><strong>No Personal Information Collected:</strong> We do <strong>NOT</strong> require or request registration, account creation, real names, email addresses, phone numbers, physical addresses, or any personal identifying information (PII) from children.</li>\n      <li><strong>100% Free & Anonymous Access:</strong> Every coloring page, interactive digital coloring studio tool, category, and printable line-art drawing is accessible instantly and completely anonymously without sign-in or login.</li>\n      <li><strong>No Social Sharing or Chat:</strong> There are no public chat rooms, public forums, or unmoderated social sharing channels on ColoringTool.com where children could inadvertently post or expose personal details.</li>\n    </ul>\n\n    <h2>2. Google AdSense & Third-Party Advertising Policy Compliance</h2>\n    <p>To keep all 100+ coloring activities free for families, homeschoolers, and classrooms, we display non-intrusive advertisements served through trusted partners, primarily <strong>Google AdSense</strong>. We strictly adhere to Google’s Publisher Policies regarding advertising disclosures and cookie usage:</p>\n    <ul>\n      <li><strong>Third-Party Cookies & Web Beacons:</strong> Third-party vendors, including Google, use cookies, web beacons, or unique device identifiers to serve advertisements based on a user’s prior visits to this website or other websites across the Internet.</li>\n      <li><strong>Google Advertising & DoubleClick Cookies:</strong> Google’s use of advertising cookies enables it and its partners to serve relevant advertisements to users based on their navigation history across the web.</li>\n      <li><strong>Non-Personalized Ads for Child Audiences:</strong> In accordance with Google’s policy for child-directed websites and COPPA standards, advertisements shown on child-directed pages are requested as <strong>non-personalized ads</strong>. Non-personalized ads do not use cookies for user profiling or behavioral tracking; they rely strictly on contextual factors (such as the content of the page or general coarse geographic location).</li>\n      <li><strong>How Users & Parents Can Opt Out of Personalized Advertising:</strong>\n        <ul>\n          <li>Users and parents may opt out of personalized advertising by visiting Google's official <a href=\"https://www.google.com/settings/ads\" target=\"_blank\" rel=\"noopener noreferrer\">Google Ads Settings</a> (or <a href=\"https://adssettings.google.com\" target=\"_blank\" rel=\"noopener noreferrer\">https://adssettings.google.com</a>).</li>\n          <li>Alternatively, you can opt out of a wide array of third-party advertising vendors' use of cookies for personalized advertising by visiting the Digital Advertising Alliance at <a href=\"https://www.aboutads.info\" target=\"_blank\" rel=\"noopener noreferrer\">www.aboutads.info</a>, <a href=\"https://youradchoices.com\" target=\"_blank\" rel=\"noopener noreferrer\">YourAdChoices</a>, or the Network Advertising Initiative (NAI) at <a href=\"https://optout.networkadvertising.org\" target=\"_blank\" rel=\"noopener noreferrer\">optout.networkadvertising.org</a>.</li>\n          <li>For visitors located in the European Economic Area (EEA) and the United Kingdom, you can also manage your consent preferences via the European Interactive Digital Advertising Alliance (EDAA) at <a href=\"https://www.youronlinechoices.eu\" target=\"_blank\" rel=\"noopener noreferrer\">www.youronlinechoices.eu</a>.</li>\n        </ul>\n      </li>\n    </ul>\n\n    <h2>3. Google Analytics & Aggregate Performance Metrics</h2>\n    <p>We use <strong>Google Analytics 4 (GA4)</strong> to understand broad website performance trends, such as aggregate page views, most popular coloring categories, and general device compatibility. Google Analytics collects anonymized technical information (such as browser type, approximate country/city level location, screen resolution, and time spent on page). We have configured Google Analytics with IP anonymization and we do not connect analytic data to personal identities.</p>\n\n    <h2>4. Browser Local Storage (\"My Art Gallery\")</h2>\n    <p>ColoringTool.com features an interactive <strong>\"My Art Gallery\"</strong> tool that allows children to save their colored artwork so they can revisit, reprint, or download their creations later. All saved artwork is stored <strong>exclusively inside your device’s local browser storage (HTML5 LocalStorage)</strong>. Artwork data is never transmitted to, uploaded, or stored on our external servers.</p>\n\n    <h2>5. User Rights Under GDPR & CCPA/CPRA</h2>\n    <p>Depending on your jurisdiction (such as the European Union, United Kingdom, or California), you hold rights regarding data protection:</p>\n    <ul>\n      <li><strong>Right of Access & Deletion:</strong> Because we do not collect personal profiles, accounts, or emails, we store no personal records of your browsing. You can erase all locally saved artwork and cookies at any time by clearing your web browser’s cache and local storage.</li>\n      <li><strong>\"Do Not Sell My Personal Information\":</strong> ColoringTool.com does <strong>NOT</strong> sell, rent, or trade any personal information of any user, regardless of age.</li>\n    </ul>\n\n    <h2>6. Changes to this Privacy Policy</h2>\n    <p>We may periodically update this Privacy Policy to reflect platform enhancements or changes in legal regulations. When updates occur, the \"Effective Date\" at the top of this document will be revised accordingly.</p>\n\n    <h2>7. Contact Us & Privacy Officer</h2>\n    <p>If you have any questions, feedback, or parental inquiries regarding our child privacy practices or advertising disclosures, please reach out to us directly:</p>\n    <ul>\n      <li><strong>Email:</strong> <a href=\"mailto:privacy@coloringtool.com\">privacy@coloringtool.com</a> or <a href=\"mailto:contact@coloringtool.com\">contact@coloringtool.com</a></li>\n      <li><strong>Contact Page:</strong> <a href=\"/contact.html\">ColoringTool.com Contact Us</a></li>\n      <li><strong>Response Window:</strong> We review and reply to all parent and educator inquiries within 24–48 business hours.</li>\n    </ul>\n  ","termsHtml":"\n    <h2>Terms of Use — ColoringTool.com</h2>\n    <p><strong>Effective Date:</strong> November 15, 2026</p>\n    <p>Welcome to <strong>ColoringTool.com</strong>. By accessing, browsing, or using this website, including all digital coloring pages, vector studio painting tools, downloadable line-art illustrations, and educational resources, you agree to comply with and be bound by the following Terms of Use. If you do not agree with these terms, please do not use this website.</p>\n\n    <h2>1. Purpose & Educational Mission</h2>\n    <p>ColoringTool.com is an online platform created to provide children, families, parents, teachers, and caregivers with free, accessible, and creative digital coloring experiences. All interactive studio features, color palettes, and printable sheets are provided free of charge for recreational, personal, and educational enrichment.</p>\n\n    <h2>2. Permitted Use & Classroom License</h2>\n    <p>We encourage creativity and learning! Subject to these Terms of Use, ColoringTool.com grants you a non-exclusive, revocable, royalty-free license to:</p>\n    <ul>\n      <li><strong>Personal & Family Use:</strong> Color online, save your artwork locally, and download or print coloring drawings for personal, non-commercial entertainment.</li>\n      <li><strong>Classroom & Educational License:</strong> Teachers, educators, homeschooling groups, daycare providers, and libraries are warmly permitted to print, photocopy, and distribute our line-art coloring pages for in-class activities and educational instruction at no cost.</li>\n    </ul>\n\n    <h2>3. Restrictions on Commercial Use & Scraping</h2>\n    <p>To protect our creative artists and maintain a safe platform, the following activities are strictly prohibited:</p>\n    <ul>\n      <li>You may <strong>NOT</strong> resell, sublicense, republish for profit, or package our digital artwork, game code, vector assets, or illustrations into commercial products, paid coloring books, or commercial apps without prior written consent from ColoringTool.com.</li>\n      <li>You may <strong>NOT</strong> use automated bots, scrapers, data-mining tools, or bulk downloaders to extract artwork, assets, or server endpoints.</li>\n      <li>You may <strong>NOT</strong> bypass, tamper with, or interfere with website security, server integrity, or ad-serving infrastructure.</li>\n    </ul>\n\n    <h2>4. Intellectual Property Rights</h2>\n    <p>All website design, trademarks, software code, interactive canvas tools, vector rendering scripts, visual graphics, sound effects, and curated coloring drawings are the property of ColoringTool.com and its content licensors, protected by international copyright, trademark, and intellectual property laws.</p>\n\n    <h2>5. Third-Party Advertising & External Links</h2>\n    <p>To maintain free access for all children and educators, ColoringTool.com displays advertisements provided by trusted networks, including Google AdSense. We strive to ensure all advertisements are child-appropriate and compliant with Google's child-directed ad policies. We do not control third-party advertiser websites and are not responsible for their external content, privacy practices, or products.</p>\n\n    <h2>6. Disclaimer of Warranties</h2>\n    <p>ColoringTool.com and all materials, drawings, tools, and content are provided on an <strong>\"AS IS\"</strong> and <strong>\"AS AVAILABLE\"</strong> basis without warranties of any kind, either express or implied. While we strive for uninterrupted, bug-free experiences, we do not warrant that the website will always be error-free or uninterrupted.</p>\n\n    <h2>7. Limitation of Liability</h2>\n    <p>In no event shall ColoringTool.com, its creators, operators, or affiliates be liable for any direct, indirect, incidental, or consequential damages resulting from the use of, or inability to use, this website or its downloadable materials.</p>\n\n    <h2>8. Modifications to Terms</h2>\n    <p>We reserve the right to revise these Terms of Use at any time. Any revisions become effective immediately upon posting to this page with an updated effective date.</p>\n\n    <h2>9. Contact Information</h2>\n    <p>If you have any questions, licensing inquiries, classroom requests, or copyright notices regarding these Terms of Use, please contact us:</p>\n    <ul>\n      <li><strong>Email:</strong> <a href=\"mailto:contact@coloringtool.com\">contact@coloringtool.com</a> or <a href=\"mailto:legal@coloringtool.com\">legal@coloringtool.com</a></li>\n      <li><strong>Contact Form:</strong> <a href=\"/contact.html\">ColoringTool.com Contact Us Page</a></li>\n    </ul>\n  ","contactHtml":"\n    <h2>Contact Us — ColoringTool.com</h2>\n    <p>Have a question, feedback, drawing suggestion, or educational inquiry? We’d love to hear from you! At <strong>ColoringTool.com</strong>, we are committed to providing the highest quality experience for children, parents, teachers, and guardians.</p>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(260px, 1fr));gap:20px;margin:28px 0;\">\n      <div style=\"background:#F8FAFC;border:1px solid #E2E8F0;border-radius:14px;padding:20px;\">\n        <div style=\"font-size:2rem;margin-bottom:8px;\">📧</div>\n        <h3 style=\"margin:0 0 6px;\">Direct Email Support</h3>\n        <p style=\"color:#64748B;font-size:0.95rem;margin:0 0 8px;\">General, technical, or drawing questions:</p>\n        <a href=\"mailto:contact@coloringtool.com\" style=\"color:var(--primary);font-weight:700;font-size:1.05rem;\">contact@coloringtool.com</a>\n      </div>\n      <div style=\"background:#F8FAFC;border:1px solid #E2E8F0;border-radius:14px;padding:20px;\">\n        <div style=\"font-size:2rem;margin-bottom:8px;\">🔒</div>\n        <h3 style=\"margin:0 0 6px;\">Privacy & COPPA Office</h3>\n        <p style=\"color:#64748B;font-size:0.95rem;margin:0 0 8px;\">Child safety and data protection inquiries:</p>\n        <a href=\"mailto:privacy@coloringtool.com\" style=\"color:var(--primary);font-weight:700;font-size:1.05rem;\">privacy@coloringtool.com</a>\n      </div>\n      <div style=\"background:#F8FAFC;border:1px solid #E2E8F0;border-radius:14px;padding:20px;\">\n        <div style=\"font-size:2rem;margin-bottom:8px;\">⏱️</div>\n        <h3 style=\"margin:0 0 6px;\">Response Window</h3>\n        <p style=\"color:#64748B;font-size:0.95rem;margin:0;\">We personally read every inquiry and reply within <strong>24 to 48 business hours</strong> (Monday–Friday).</p>\n      </div>\n    </div>\n\n    <h2>Send Us a Message</h2>\n    <p style=\"color:#64748B;\">Please fill out the form below and our team will get back to you promptly:</p>\n\n    <form id=\"contactForm\" onsubmit=\"event.preventDefault();handleContactSubmit();\" style=\"background:#F8FAFC;border:1px solid #E2E8F0;border-radius:16px;padding:26px;margin:20px 0;\">\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;margin-bottom:16px;\">\n        <div>\n          <label style=\"display:block;font-weight:600;margin-bottom:6px;color:#1E293B;\">Your Name *</label>\n          <input type=\"text\" id=\"contactName\" required placeholder=\"e.g. Sarah Jenkins\" class=\"form-control\" style=\"width:100%;padding:10px 14px;border-radius:8px;border:1px solid #CBD5E1;font-size:1rem;\">\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;margin-bottom:6px;color:#1E293B;\">Your Email Address *</label>\n          <input type=\"email\" id=\"contactEmail\" required placeholder=\"e.g. sarah@example.com\" class=\"form-control\" style=\"width:100%;padding:10px 14px;border-radius:8px;border:1px solid #CBD5E1;font-size:1rem;\">\n        </div>\n      </div>\n\n      <div style=\"margin-bottom:16px;\">\n        <label style=\"display:block;font-weight:600;margin-bottom:6px;color:#1E293B;\">Subject / Topic *</label>\n        <select id=\"contactTopic\" class=\"form-control\" style=\"width:100%;padding:10px 14px;border-radius:8px;border:1px solid #CBD5E1;font-size:1rem;\">\n          <option value=\"General Question\">General Inquiry / Feedback</option>\n          <option value=\"Drawing Suggestion\">New Drawing Suggestion (Animals, Unicorns, etc.)</option>\n          <option value=\"Classroom / School Inquiry\">Teacher / Classroom Educational Use</option>\n          <option value=\"Bug / Technical Issue\">Bug Report / Technical Issue</option>\n          <option value=\"Privacy / COPPA\">Child Privacy / COPPA Inquiry</option>\n          <option value=\"Copyright / DMCA\">Copyright or Trademark Licensing</option>\n        </select>\n      </div>\n\n      <div style=\"margin-bottom:20px;\">\n        <label style=\"display:block;font-weight:600;margin-bottom:6px;color:#1E293B;\">Your Message *</label>\n        <textarea id=\"contactMessage\" required rows=\"5\" placeholder=\"Write your message or question here...\" class=\"form-control\" style=\"width:100%;padding:12px 14px;border-radius:8px;border:1px solid #CBD5E1;font-size:1rem;\"></textarea>\n      </div>\n\n      <button type=\"submit\" id=\"contactSubmitBtn\" style=\"background:#4F46E5;color:white;border:none;padding:12px 28px;border-radius:25px;font-weight:700;font-size:1rem;cursor:pointer;transition:background 0.2s;\">✉️ Send Message</button>\n      <div id=\"contactSuccessMsg\" style=\"display:none;margin-top:16px;background:#D1FAE5;border:1px solid #10B981;color:#065F46;padding:12px 16px;border-radius:8px;font-weight:600;\">\n        🎉 Thank you for reaching out! Your message has been received. Our team will review it and reply within 24–48 hours.\n      </div>\n    </form>\n\n    <h2>Frequently Asked Questions (FAQ)</h2>\n    <div style=\"margin-top:16px;display:flex;flex-direction:column;gap:12px;\">\n      <div style=\"background:#FFFFFF;border:1px solid #E2E8F0;border-radius:10px;padding:16px;\">\n        <strong style=\"color:#1E293B;font-size:1.05rem;\">Is ColoringTool.com 100% free?</strong>\n        <p style=\"color:#64748B;margin:6px 0 0;\">Yes! All 100+ drawings, interactive coloring tools, and printables are completely free without any subscriptions or paid locks.</p>\n      </div>\n      <div style=\"background:#FFFFFF;border:1px solid #E2E8F0;border-radius:10px;padding:16px;\">\n        <strong style=\"color:#1E293B;font-size:1.05rem;\">Can teachers print drawings for school classrooms?</strong>\n        <p style=\"color:#64748B;margin:6px 0 0;\">Absolutely! We provide an open educational license for teachers, daycare centers, and libraries to print and photocopy drawings for in-class learning activities.</p>\n      </div>\n      <div style=\"background:#FFFFFF;border:1px solid #E2E8F0;border-radius:10px;padding:16px;\">\n        <strong style=\"color:#1E293B;font-size:1.05rem;\">Do you collect personal information from children?</strong>\n        <p style=\"color:#64748B;margin:6px 0 0;\">No. In accordance with COPPA regulations, we never collect personal identifying information from children under 13. Access is 100% anonymous.</p>\n      </div>\n    </div>\n  "};
